<?php
declare(strict_types=1);
require_once __DIR__.'/../config.php';require_login();sodium_require_aptitude('sodium_full_access');require_once __DIR__.'/../includes/layout.php';
$settings=sodium_instance_settings();
if($_SERVER['REQUEST_METHOD']==='POST'){$accountId=(int)($_POST['system_mail_account_id']??0);if($accountId){$check=$pdo->prepare('SELECT COUNT(*) FROM sodium_mail_accounts WHERE id=?');$check->execute([$accountId]);if(!$check->fetchColumn())$accountId=0;}$timezone=in_array($_POST['timezone']??'',['Europe/Paris','UTC','Europe/Brussels','Europe/Luxembourg','Europe/Zurich'],true)?(string)$_POST['timezone']:'Europe/Paris';sodium_save_instance_settings(['instance_name'=>trim((string)($_POST['instance_name']??'Sodium'))?:'Sodium','organization_name'=>trim((string)($_POST['organization_name']??'')),'support_email'=>trim((string)($_POST['support_email']??'')),'system_mail_account_id'=>(string)$accountId,'system_sender_name'=>trim((string)($_POST['system_sender_name']??'Sodium'))?:'Sodium','timezone'=>$timezone]);flash('success','Paramètres généraux enregistrés.');redirect('/admin/settings.php');}
$accounts=$pdo->query("SELECT id,display_name,email_address FROM sodium_mail_accounts WHERE account_status='active' ORDER BY display_name,email_address")->fetchAll();$settings=sodium_instance_settings();sodium_render_header('Paramètres généraux');?>
<form method="post" class="row g-4"><div class="col-12"><div class="form-card"><h2 class="h5 mb-3">Instance Sodium</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">Nom de l’instance</label><input class="form-control" name="instance_name" value="<?=e($settings['instance_name'])?>" required></div><div class="col-md-6"><label class="form-label">Organisation titulaire</label><input class="form-control" name="organization_name" value="<?=e($settings['organization_name'])?>"></div><div class="col-md-6"><label class="form-label">Adresse de support</label><input class="form-control" type="email" name="support_email" value="<?=e($settings['support_email'])?>"></div><div class="col-md-6"><label class="form-label">Fuseau horaire</label><select class="form-select" name="timezone"><?php foreach(['Europe/Paris','UTC','Europe/Brussels','Europe/Luxembourg','Europe/Zurich'] as $zone):?><option <?=$settings['timezone']===$zone?'selected':''?>><?=e($zone)?></option><?php endforeach;?></select></div></div></div></div><div class="col-12"><div class="form-card"><h2 class="h5 mb-1">Compte système</h2><p class="text-muted">Compte utilisé pour les notifications système et les messages de réinitialisation de mot de passe.</p><div class="row g-3"><div class="col-md-6"><label class="form-label">Compte mail expéditeur</label><select class="form-select" name="system_mail_account_id"><option value="0">Non configuré</option><?php foreach($accounts as $account):?><option value="<?=(int)$account['id']?>" <?=(int)$settings['system_mail_account_id']===(int)$account['id']?'selected':''?>><?=e($account['display_name']?:$account['email_address'])?> — <?=e($account['email_address'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Nom d’expéditeur système</label><input class="form-control" name="system_sender_name" value="<?=e($settings['system_sender_name'])?>"></div></div></div></div><div class="col-12"><button class="btn btn-danger" type="submit"><i class="bi bi-check-lg me-2"></i>Enregistrer</button></div></form>
<?php sodium_render_footer();?>
